from phase0_v2.conflicts.preprocessing import extract_content

def _words_absent_fixed(r, a):
    content = extract_content(r, 'forbidden_words')
    if content is None:
        content = r
    if not content.strip():
        return True  # bare refusal trivially avoids
    cleaned = _strip_quoted_words(content)
    return all(no_word_in_text(w, cleaned) for w in _WORDS)

def _words_present_fixed(r, a):
    content = extract_content(r, 'forbidden_words')
    if content is None:
        content = r
    if not content.strip():
        return False  # bare refusal has no content
    cleaned = _strip_quoted_words(content)
    return all(word_or_morphform_in_text(w, cleaned) for w in _WORDS)
